css:
.fx-mt{width:min(1060px,100%);display:grid;gap:clamp(1.4em,4vw,2.4em)}
.fx-mt .eye{font-size:.78em;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--accent)}
.mt{--mp:.5;display:grid;gap:.1em}
.mt-t{margin:0;font-family:var(--font-heading);font-weight:800;text-transform:uppercase;letter-spacing:-.04em;line-height:.88;font-size:clamp(3.6em,18vw,11.5em)}
.mt-t span{display:block;width:fit-content;color:var(--primary);padding-bottom:.04em}
@supports ((-webkit-background-clip:text) or (background-clip:text)){
.mt-a,.mt-b{color:transparent;-webkit-text-fill-color:transparent;-webkit-background-clip:text;background-clip:text}
.mt-a{background-image:radial-gradient(circle at 52% 40%,color-mix(in srgb,var(--surface) 90%,var(--accent)) 0 8.5%,transparent 8.9%),linear-gradient(to bottom,color-mix(in srgb,var(--accent) 55%,#fff) 0,var(--accent) 30%,color-mix(in srgb,var(--accent) 55%,var(--primary)) 48%,var(--primary) 50%,color-mix(in srgb,var(--primary) 55%,var(--secondary)) 72%,var(--primary) 100%);background-size:100% 220%;background-position:50% calc(var(--mp)*100%)}
.mt-b{background-image:conic-gradient(from calc(var(--mp)*300deg) at 50% 60%,var(--primary),var(--accent),var(--secondary),color-mix(in srgb,var(--accent) 50%,var(--surface)),var(--primary))}}
.fx-mt p.lead{max-width:34em;opacity:.7;font-size:1.05em}
.fx-mt .hint{font-size:.8em;opacity:.5;letter-spacing:.08em;text-transform:uppercase}

js:
(function(){
var els=[].slice.call(document.querySelectorAll('.fx-mt [data-mt]'));
if(!els.length||(window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches))return;
var raf=0;
function cl(v){return v<0?0:v>1?1:v}
function upd(){raf=0;var vh=window.innerHeight||800;
 els.forEach(function(el){var r=el.getBoundingClientRect();el.style.setProperty('--mp',cl((vh-r.top)/(vh+r.height)).toFixed(3))})}
function req(){if(!raf)raf=requestAnimationFrame(upd)}
addEventListener('scroll',req,{passive:true});addEventListener('resize',req);upd();
})();
